const $=s=>document.querySelector(s);
const scenes=[['opening','初见平川','开局 · 第一刻','不是等一个进度条，而是看见第一顿饭、第一束炊烟。'],['day','白昼生活','日常 · 城中一日','农人下田，挑夫过桥，饭菜送到家。每一个小人都有去处。'],['logistics','一餐的旅程','生产 · 批次与配送','从田边到餐桌，让“正在生产”和“已经吃到”一眼可分。'],['husbandry','牧栏与肉食','养殖 · 可选生活链','两头猪，一条完整的生活链。缺粮时安全等待，不制造焦虑。'],['night','暮归与夜巡','夜晚 · 安静也有故事','窗灯陆续亮起，日班返家，夜巡接过这座城。'],['construction','一砖一瓦','营造 · 城市生长','材料真的到场，工人真的施工，房子从地基慢慢长出来。'],['direction','城市的性格','方针 · 四条特色工程','改变未来优先级，不推倒已经建好的生活。'],['heroes','城中有故人','宝鉴 · 名将与珍藏','不是抽卡大厅。名将沿着城市的生活与事业逐步到来。'],['army','南门点兵','军团 · 设计目标','授权不等于兵员，饭菜不等于军粮。准备齐了，才谈出发。'],['region','山河之间','区域 · 设计目标','从一城到三城，路程、运输与迁居都留下真实的时间。'],['memories','小城成长册','记忆 · 同一角度看变化','不催你上线。回来时，看看这座城又留下了什么。'],['desktop','回到你的桌面','桌面 · 低打扰陪伴','工作仍然是主角，小城在一旁生活。']];
const state={scene:'opening',opening:0,meal:2,pig:1,build:45,policy:0,heroTab:0,heroFilter:'全部',query:'',army:30,region:0,wish:null,paused:false};
let heroes=[];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const card=(title,body,label='')=>`<article class="card">${label?`<div class="label">${label}</div>`:''}<h3>${title}</h3>${body}</article>`;
const row=(a,b)=>`<div class="row"><span>${a}</span><em>${b}</em></div>`;
const progress=n=>`<div class="progress"><i style="width:${n}%"></i></div>`;
const review=s=>`<div class="review"><strong>这一幕，想和你确认</strong>${s}</div>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function modal(title,body){$('#dialog-content').innerHTML=`<div class="label">交互演示 / 不影响真实存档</div><h2>${title}</h2>${body}`;$('#dialog').showModal()}
$('.close').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close()};
$('#motion').onclick=()=>{state.paused=!state.paused;document.body.classList.toggle('paused',state.paused);$('#motion').textContent=state.paused?'继续动效':'暂停动效'};
const buildings=[['hall','官署',1060,760],['home','槐荫居',910,760],['home','竹影居',770,750],['home','北巷民居',920,930],['farm','农庄',570,730],['store','粮仓',560,550],['market','集市',910,550],['forge','百工坊',1370,540],['kitchen','共用厨房',1060,550],['stable','牧栏',1540,470],['station','驿站',1460,290],['camp','军营',1610,740],['home','东厢民居',1080,930],['store','北仓',580,930],['farm','南田农庄',570,470],['forge','修复工坊',1370,790]];
function defs(){return `<defs><pattern id="grass" width="58" height="51" patternUnits="userSpaceOnUse"><path d="M8 16l3-5 3 5M40 39l2-4 3 4" fill="none" stroke="#acbb8c" opacity=".3"/></pattern><pattern id="tiles" width="11" height="8" patternUnits="userSpaceOnUse"><path d="M0 7h11M5 0v7" stroke="#9ca493" stroke-width=".8" fill="none"/></pattern><pattern id="crops" width="22" height="25" patternUnits="userSpaceOnUse"><path d="M11 23V7M11 14l-5-5m5 10 6-8" stroke="#7c9853" stroke-width="3" fill="none"/><ellipse cx="11" cy="6" rx="3" ry="5" fill="#d5bd62"/></pattern><symbol id="tree" viewBox="-35 -65 70 90"><ellipse cy="19" rx="29" ry="8" fill="#708651" opacity=".17"/><path d="M0 17V-29m0 20-15-14m15 8 14-17" stroke="#8c8161" stroke-width="5"/><circle cy="-34" r="22" fill="#779661"/><circle cx="-17" cy="-18" r="17" fill="#8ca56b"/><circle cx="17" cy="-19" r="19" fill="#688b60"/><circle cy="-27" r="15" fill="#92aa72"/></symbol><symbol id="person" viewBox="-12 -32 24 42"><ellipse cy="8" rx="10" ry="3" fill="#324833" opacity=".25"/><path d="M-4 0l-2 7M4 0l2 7" stroke="#414c43" stroke-width="4"/><path d="M-7 1l2-18h10L8 1Z" fill="currentColor"/><circle cy="-23" r="6" fill="#deb78a"/><path d="M-6-24v-5h12v5m-8-6v-3h4v3" fill="#344d43"/><path d="M-6-13l-4 8m16-8 4 8" stroke="#c9a879" stroke-width="3"/></symbol><symbol id="pig" viewBox="-28 -20 56 42"><ellipse cy="16" rx="25" ry="5" fill="#829162" opacity=".25"/><path d="M-14 7v9m24-8v8" stroke="#b58c7d" stroke-width="5"/><ellipse rx="22" ry="13" fill="#debaa3"/><circle cx="18" cy="-2" r="11" fill="#eccbb4"/><path d="M12-10l-2-10 10 8" fill="#cf9e91"/><ellipse cx="25" cy="1" rx="6" ry="5" fill="#c7958b"/><circle cx="20" cy="-4" r="1.5" fill="#574f47"/></symbol></defs>`}
function building(type,x,y,label,idx,construction=false){let roof=type==='hall'?'#506c60':type==='kitchen'?'#98664e':type==='camp'?'#646e5b':'#758170';let w=type==='hall'?105:78;let h=type==='hall'?65:48;let shape=type==='stable'?`<rect x="-75" y="-36" width="150" height="72" rx="8" fill="#bbbc8b"/><path d="M-75-30v64h150v-64M-75 3H75" fill="none" stroke="#998666" stroke-width="7"/>${[-60,-30,0,30,60].map(a=>`<path d="M${a} -31v65" stroke="#b09a74" stroke-width="5"/>`).join('')}<use href="#pig" x="-47" y="-30" width="48" height="36"/><use href="#pig" x="10" y="-25" width="40" height="30"/>`:`<rect x="${-w-9}" y="-21" width="${w*2+18}" height="69" rx="8" fill="#c6c49e"/><rect x="${-w}" y="${-h}" width="${2*w}" height="${h+32}" fill="#ded5af" stroke="#b2aa85" stroke-width="2"/><path d="M${w-10} ${-h}V30H${w}" fill="#bdb891"/><rect x="-15" y="-8" width="30" height="40" fill="#536b57"/><path d="M-12-8v40M0-8v40M12-8v40" stroke="#839071" stroke-width="2"/>${[-w+20,w-40].map(a=>`<rect x="${a}" y="${-h+18}" width="23" height="20" fill="#9aa991" stroke="#7b886e"/><path d="M${a+11} ${-h+18}v20" stroke="#d8ceb0"/>`).join('')}<path d="M${-w-15} ${-h+5}Q${-w+8} ${-h-5} ${-w+22} ${-h-35}H${w-22}Q${w-8} ${-h-5} ${w+15} ${-h+5}Z" fill="${roof}" stroke="#536b5b" stroke-width="3"/><path d="M${-w-15} ${-h+5}Q${-w+8} ${-h-5} ${-w+22} ${-h-35}H${w-22}Q${w-8} ${-h-5} ${w+15} ${-h+5}Z" fill="url(#tiles)"/><path d="M${-w+19} ${-h-35}h${w*2-38}" stroke="#a9ae94" stroke-width="5"/><rect x="-30" y="${-h+10}" width="60" height="17" rx="2" fill="#e7dfba"/><text y="${-h+23}" text-anchor="middle" font-size="10" fill="#586c57">${label}</text>${type==='kitchen'||type==='forge'?`<g class="smoke" fill="#faf7e4" opacity=".65"><circle cx="55" cy="-101" r="9"/><circle cx="58" cy="-120" r="12"/><circle cx="51" cy="-141" r="15"/></g>`:''}${type==='market'?`<path d="M-65 20h130l-14-24H-51Z" fill="#b67651"/><path d="M-60 20v28m120-28v28" stroke="#8d7959" stroke-width="4"/><circle cx="-40" cy="32" r="8" fill="#d6bb65"/><circle cx="-19" cy="32" r="8" fill="#a0ab64"/>`:''}<g class="lantern"><circle cx="-48" cy="-6" r="38" fill="#f4bc63" opacity=".15"/><rect x="-54" y="-16" width="12" height="18" rx="4" fill="#f3c37a"/></g>`;
if(construction)shape=`<rect x="-95" y="-40" width="190" height="85" fill="#c6bd9a" stroke="#a89770" stroke-dasharray="7 6"/>${state.build>=20?`<path d="M-70 30v-95m140 95v-95M-70-57H70M-70 2H70M-35 30v-105m70 105v-105" stroke="#9b7e53" stroke-width="7" fill="none"/>`:''}${state.build>=45?`<path d="M-92-60l35-50H57l35 50Z" fill="#8d9776" opacity=".8"/>`:''}${state.build>=80?`<rect x="-70" y="-58" width="140" height="82" fill="#ded5af"/><rect x="-15" y="-15" width="30" height="39" fill="#6c7b60"/>`:''}<path d="M-112 30V-100m20 130V-100m-20 20h20m-20 30h20m-20 30h20" stroke="#b5996c" stroke-width="3"/><path d="M95 31h40m-40-9h40m-40-9h40" stroke="#9b815a" stroke-width="7"/>`;
return `<g class="map-building" data-building="${idx}" role="button" tabindex="0" aria-label="查看${label}" transform="translate(${x} ${1080-y})"><ellipse cy="36" rx="${w+24}" ry="19" fill="#7b9064" opacity=".18"/>${shape}<text class="map-label" text-anchor="middle" y="65">${label}${construction?' · 施工中':''}</text></g>`}
function map(opts={}){const young=opts.young,night=opts.night,focus=opts.focus||'0 0 1920 1080';let trees='';for(let i=0;i<40;i++){let x=i<20?70+(i%5)*62:1220+(i%7)*78,y=i<20?110+Math.floor(i/5)*66:75+Math.floor((i-20)/7)*47;trees+=`<use href="#tree" x="${x}" y="${y}" width="68" height="88"/>`}
let fields='';for(let r=0;r<6;r++)for(let c=0;c<4;c++){let x=210+c*75,y=1080-[260,330,450,520,720,790][r];let active=!young||(r===5);fields+=`<g><rect x="${x-27}" y="${y-25}" width="58" height="49" rx="5" fill="${active?'#b3ad72':'#c4bd94'}" stroke="#d2caaa" stroke-width="4"/><path d="M${x-23} ${y-10}h48m-48 13h48m-48 13h48" stroke="#a39c77" stroke-width="2"/>${active?`<rect x="${x-23}" y="${y-22}" width="49" height="42" fill="url(#crops)"/>`:''}</g>`}
const ids=young?[0,1,4,5,8]:buildings.map((_,i)=>i);let houses=ids.map(i=>{const [type,label,x,y]=buildings[i];return building(type,x,y,label,i,opts.build&&i===7&&state.build<100)}).join('');
let actors='';for(let i=0;i<(night?4:16);i++){let path=i%3===0?'M680 440 L680 240 L1050 240 L1200 240 L1200 440 L680 440':i%3===1?'M680 440 L680 700 L1200 700 L1200 440 L680 440':'M1200 440 L1780 440 L1780 880 L1200 880 L1200 440';actors+=`<g class="actor" style="offset-path:path('${path}');animation-duration:${25+i*1.7}s;animation-delay:-${i*6}s;color:${night?'#8d9b84':['#52796c','#af7653','#7d8c62','#657986'][i%4]}"><g data-worker="${i}" role="button" tabindex="0" aria-label="查看居民"><use href="#person" x="-12" y="-32" width="24" height="42"/>${night?'<circle cx="13" cy="-14" r="24" fill="#f7c66e" opacity=".18"/><circle cx="13" cy="-14" r="4" fill="#ffd281"/>':i%3===0?'<path d="M-17-12h34" stroke="#8b7650" stroke-width="2"/><rect x="-21" y="-11" width="12" height="13" rx="3" fill="#c4aa66"/><rect x="9" y="-11" width="12" height="13" rx="3" fill="#c4aa66"/>':''}</g></g>`}
return `<div class="scene ${night?'night':''}"><svg viewBox="${focus}" role="img" aria-label="平川生活场景，可点击建筑和居民查看详情">${defs()}<rect class="map-ground" width="1920" height="1080"/><g class="terrain"><rect width="1920" height="1080" fill="url(#grass)"/><path d="M1850-80Q1590 170 1770 380T1710 780T1650 1200" stroke="#b9cdb5" stroke-width="170" fill="none"/><path d="M1850-80Q1590 170 1770 380T1710 780T1650 1200" stroke="#91b9ac" stroke-width="118" fill="none"/><path d="M1840-80Q1580 170 1760 380T1700 780T1640 1200" stroke="#bed8c4" stroke-width="3" fill="none" stroke-dasharray="30 40"/><path d="M105 130H1640M105 960H1680M105 130V960" fill="none" stroke="#a0ad88" stroke-width="17"/><path d="M105 120H1640M105 950H1680" stroke="#bdc6a5" stroke-width="8" fill="none"/>${[140,680,1200,1780].map(x=>`<path d="M${x} 80V940" stroke="#ddd0ab" stroke-width="24"/>`).join('')}${[200,380,640,840,1000].map(y=>`<path d="M140 ${1080-y}H1780" stroke="#dfd1ad" stroke-width="25"/>`).join('')}${ids.map(i=>{let b=buildings[i];let sx=[680,1200,1780].reduce((a,v)=>Math.abs(v-b[2])<Math.abs(a-b[2])?v:a,680);return `<path d="M${b[2]} ${1080-b[3]+35}v35H${sx}" stroke="#dfd1ad" stroke-width="16" fill="none"/>`}).join('')}<path d="M1708 443h122M1708 424h122M1708 462h122" stroke="#b9aa84" stroke-width="9"/><path d="M1708 427h122" stroke="#e0d4af" stroke-width="6"/>${trees}${fields}<ellipse cx="775" cy="517" rx="33" ry="17" fill="#b3b695"/><ellipse cx="775" cy="506" rx="21" ry="12" fill="#93ada0" stroke="#d2ccb0" stroke-width="9"/><path d="M747 501v-40m55 40v-40m-55 0h55" stroke="#8e8464" stroke-width="5"/>${houses}<g transform="translate(1510 879)"><path d="M-90 25v-85h42v85m96 0v-85h42v85" stroke="#a1ac89" stroke-width="16"/><path d="M-107-58l24-31H83l24 31Z" fill="#617b65"/><text class="map-label" y="60" text-anchor="middle">南门</text></g><g fill="#9da68a"><path d="M142 909l28-45 41 8 28 43Z"/><path d="M345 941l40-50 40 12 25 38Z"/></g></g>${opts.route?`<path d="M430 290L680 290V440H1050V500H1200V240H930" stroke="#b85e3f" stroke-width="7" fill="none" stroke-dasharray="12 9" opacity=".8"/><g fill="#b85e3f">${[[430,290],[680,440],[1050,500],[930,240]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="16"/><text x="${x}" y="${y+5}" text-anchor="middle" fill="white" font-size="14">${i+1}</text>`).join('')}</g>`:''}${actors}</svg>${opts.overlay===false?'':`<div class="scene-top"><strong>${night?'暮色入平川':'平川 · '+(young?'开城第一日':'烟火正好')}</strong><div>${opts.line||'正在：厨师备餐，挑夫送粮'}</div><p>接下来：${night?'巡兵换岗，住民安歇':young?'第一批粟即将成熟':'新一批饭菜送往北巷'}</p></div><div class="scene-bottom"><span>${night?'夜 · 窗灯与巡逻':'昼 · 点击房屋或居民看看'}　/　演示快照</span><button data-action="follow">跟随挑夫 ↗</button></div>`}</div>`}
function stats(young=false){return `<div class="statbar">${[['居民',young?'16':'32'],['铜钱',young?'600':'1,280'],['食粮',young?'64':'96'],['肉料',young?'0':'8'],['饭菜',young?'32':'48'],['军粮','0'],['木材',young?'40':'72'],['石材',young?'12':'28'],['铁料',young?'6':'12'],['器材',young?'4':'8']].map(([a,b])=>`<div class="stat"><span>${a}</span><b>${b}</b></div>`).join('')}</div>`}
function opening(){let stages=['初到小城','饭香初起','第一份纪念'];return `<div class="tabs">${stages.map((s,i)=>`<button class="${state.opening===i?'active':''}" data-opening="${i}">${['00','05','15'][i]} 分钟 · ${s}</button>`).join('')}</div><div class="layout">${map({young:true,line:['正在：荀彧安排今日饭食','正在：厨师收尾，第一锅饭即将出锅','最近完成：官署修缮，木印可供制作'][state.opening]})}<div class="stack">${card('先把这一餐做好',`<p class="short">荀彧已在官署理事。15 位乡亲各司其职，你不必逐个安排工作。</p><div class="timeline"><div><strong>田里已有将熟的粟</strong><p>继承开局长势，不是点一下凭空获得粮食。</p></div><div><strong>饭菜送到，才算吃到</strong><p>沿着挑夫的脚步，看见第一份真实反馈。</p></div><div><strong>留下一枚开城木印</strong><p>一份可选的纪念，不是催促领奖。</p></div></div>`,'初来乍到')}${card(stages[state.opening],`<p class="short">${['初始：16 人、600 铜。界面只告诉你现在发生什么。','展示备料 → 出锅 → 送餐 → 食用，不要求玩家重复点击。','木印需要 10 铜、2 木材、360 人工秒。授权后由木匠完成。'][state.opening]}</p>${state.opening===2?'<button class="primary wide" data-action="seal">看看开城木印</button>':'<button class="wide" data-action="follow">去看看忙碌的乡亲</button>'}`)}</div></div>${stats(true)}${review('开局是否已经有足够的事可看？还是希望第一分钟就有一个轻量选择？')}`}
function day(){return `<div class="layout">${map()}<div class="stack">${card('这座城，正在生活',row('供餐覆盖','100%')+progress(100)+row('近期满意度','88 / 100')+'<p class="muted">演示值；不是当前游戏存档。</p>','今日小记')}${card('三件不必操心的小事','<div class="timeline"><div><strong>陈伯把木料送进工坊</strong><p>工匠不再等料，开始下一批器材。</p></div><div><strong>北巷的饭已经送到</strong><p>两位住民在家用饭，一位仍在返程。</p></div><div><strong>新住户正在看房</strong><p>只有床位与供给满足，才会迁入。</p></div></div>')}${card('轻轻看一眼','<button class="wide" data-action="worker">看看一位居民</button><p class="muted">身份、职责、携货与下一站，都可以追踪。</p>')}</div></div>${stats()}${review('生活动线和人物密度是否舒服？这版保留真实任务，不靠大量无目的的小人填满地图。')}`}
function logistics(){const names=['粮在田边','正在运送','灶上炊煮','饭已送达','真正吃到'];return `<div class="steps">${names.map((s,i)=>`<button class="${state.meal===i?'active':''}" data-meal="${i}">${i+1} · ${s}</button>`).join('')}</div><div class="layout">${map({route:true,line:'当前批次：'+names[state.meal]})}<div class="stack">${card('追踪这一锅饭',`<span class="pill">LOT · MEAL-DEMO-016</span><div class="divider"></div>${row('配方','家常饭 × 16')}${row('投入','食粮 4 + 木材 1')}${row('准备 / 炊煮 / 收尾','60 / 60 / 15 秒')}<p class="muted">不包含路程、缺料与等班；饭菜是一个资源，品质按批次记录。</p>`,'批次详情')}${card(names[state.meal],`<p class="short">${['粮食仍在田边，尚未变成厨房库存。','装货后扣除源库存；到达并卸货前，厨房不可使用。','原料进入在制品；被动炊煮时，厨师可以顺序接其他工作。','配送点已收到 16 份饭；送达不等于住民已经消费。','16 份已实际食用，批次销账，更新供餐记录。'][state.meal]}</p>${progress(state.meal*25)}<button class="primary wide" data-action="nextmeal">${state.meal===4?'重新看这趟旅程':'看下一步 →'}</button>`)}</div></div><div class="flow">${['生产','发运','到货','实际消纳'].map((s,i)=>`<div class="card ${state.meal===i+1?'current':''}"><div class="label">${s}</div><b>${state.meal>=i+1?'16':'0'}</b> <span class="muted">份</span><p>${['设备完成时生成','装货时离开源库存','卸货后目的地可用','居民吃下后结算'][i]}</p></div>`).join('')}</div>${review('这条链路能不能解释“为什么有粮却还没吃上饭”？路线是否太抢眼？')}`}
function husbandry(){const names=['授权建设','幼猪到货','牵入牧栏','照料成长','肉料交付','肉菜上桌'];return `<div class="steps">${names.map((n,i)=>`<button class="${state.pig===i?'active':''}" data-pig="${i}">${i+1} · ${n}</button>`).join('')}</div><div class="layout">${map({focus:'1130 390 770 580',line:names[state.pig],overlay:false})}<div class="stack">${card(names[state.pig],`<span class="pill">养殖 v2 · 常备目标 2 头</span><div class="divider"></div><p class="short">${['先建设牧栏与肉食台，授权不会立即生成动物。','每头 20 铜，运输 300 秒；每 6 小时购猪预算 40 铜。','有独立编号的幼猪，由实际工人从南门牵入已预留位置。','6 段成长；每段 0.25 食粮、30 秒照料、2,880 秒被动成长。','成年猪牵入肉食台，关门加工 90 人工秒，交付 8 份肉料。','4 食粮 + 2 肉料 + 1 木材 → 16 份肉菜饭，仍需配送与实际食用。'][state.pig]}</p>${progress(state.pig*20)}<button class="primary wide" data-action="nextpig">${state.pig===5?'重新看完整链路':'下一阶段 →'}</button>`)}${card('安心生长',`<p class="short">缺粮只等待，不倒退、不死亡。暂停新采购后，已购动物继续照料。</p>${row('本幕动物','PIG-001 / PIG-002')}<button class="wide" data-action="pigpause">暂停后续采购（演示）</button>`)}</div></div>${review('养殖场景目前采用同一牧栏示意图，阶段按钮用于评审说明与操作；后续可再细化每一阶段的专属动作。')}`}
function night(){return `<div class="layout">${map({night:true})}<div class="stack">${card('夜深了，城还醒着',`<div class="timeline"><div><strong>日班收尾 · 不瞬移回家</strong><p>已经装好的货先安全交付，再沿路返回。</p></div><div><strong>窗内灯暖 · 巷外灯缓</strong><p>只调整游戏图层，不给你的壁纸罩黑幕。</p></div><div><strong>巡兵交班 · 别有一番安宁</strong><p>日巡与夜巡是不同居民，夜巡白天休息。</p></div></div>`)}${card('夜间表现',`<button class="wide" data-action="patrol">查看巡逻路线</button><p class="muted">巡夜没有需要你即时响应的奖励或损失。</p>`)}</div></div>${review('夜景应当更安静，还是保留少量饭馆与巡逻的小故事？')}`}
function construction(){return `<div class="layout">${map({build:true,focus:'930 40 930 820',line:'百工坊 · 施工 '+state.build+'%'})}<div class="stack">${card('百工坊，正在长出来',`<div class="label">施工状态演示 · 非实际进度</div><div class="army-number">${state.build}<small>%</small></div><input aria-label="施工进度" id="build-range" type="range" min="0" max="100" step="5" value="${state.build}"><div class="steps">${[0,20,45,80,100].map((v,i)=>`<button data-build="${v}">${['清场','立柱','上梁','收尾','落成'][i]}</button>`).join('')}</div><p class="muted">拖动滑块看施工外观。未完工不提前给予设施效果。</p>`)}${card('施工面板',row('已到场','木材 12 / 石材 6')+row('正在施工','营造工 2 位')+row('下一阶段','按到场物料推进')+'<p class="muted">材料为展示样例。实际成本以具体工程配置为准；暂停只能停在安全点。</p>')}</div></div>${review('比直接换一张建筑图片，这样的分阶段生长是否更有“我养出来的城”的感觉？')}`}
const policies=[['安民','先让每一家吃得好','丰稔里坊'],['兴商','让来往的人留下来','南门商埠'],['兴业','让百工各展所长','百工院'],['备战','有备，而不轻启战端','安远营'],['均衡','维持稳定的生活节奏','平衡发展']];
function direction(){return `<div class="banner">目标设计 · 五方针完整特色工程尚未全部实现。这里预览选择方式与城市外观方向。</div><div class="policies">${policies.map((p,i)=>`<button class="policy ${state.policy===i?'active':''}" data-policy="${i}"><b>${p[0]}</b><p>${p[1]}</p></button>`).join('')}</div><div class="layout">${map({focus:state.policy===0?'610 0 680 560':state.policy===1?'820 440 980 640':state.policy===2?'1130 50 690 650':state.policy===3?'1210 100 680 870':'0 0 1920 1080',line:'发展方向：'+policies[state.policy][2]})}<div class="stack">${card(policies[state.policy][2],`<p>${policies[state.policy][1]}</p><div class="divider"></div>${row('未来建设优先','保持已有建筑')}${row('肉菜目标占比',[50,25,0,0,25][state.policy]+'%')}<p class="muted">方针调整未来需求与优先级，不改配方产量，不自动授权军团。</p><button class="primary wide" data-action="policy">采用${policies[state.policy][0]}方针（演示）</button>`)}${card('特色不是另一个加成按钮','<p class="short">丰稔里坊：院落、共用厨房、花园。<br>南门商埠：货栈、客舍、商街。<br>百工院：木作、锻造、修复。<br>安远营：军需、操练、望楼。</p>')}</div></div>${review('目前先复用地图局部作为工程位置示意；四条风格的独立建筑美术，是下一轮重点。')}`}
function portrait(h,i){const colors=['#406e63','#66899a','#aa7857','#77845b','#426e58','#685e50'];let c=colors[i%6],warrior=['zhaoyun','guanyu','zhangfei','lvbu','machao','huangzhong','xuchu'].includes(h.id);return `<svg viewBox="0 0 180 160" aria-hidden="true"><circle cx="90" cy="79" r="58" fill="#f7f1d9" opacity=".55"/><path d="M28 170q4-62 62-65 58 3 62 65" fill="${c}"/><path d="M68 105l22 49 22-49-22 18Z" fill="#ede5c9"/><path d="M82 129l-8 31h32l-10-31" fill="${c}"/><path d="M60 68q-4 55 30 56 34-2 30-56" fill="#d9ad83"/><path d="M57 78q-10-45 33-47 40 0 34 47l-10-14-49 1Z" fill="#35483e"/>${warrior?`<path d="M54 70q0-43 36-44 37 2 37 44l-16-9H67Z" fill="#7d8f88" stroke="#d6c49a" stroke-width="3"/><path d="M87 26V9h7v18" fill="#b56147"/>`:`<path d="M62 60V29h56v31M77 30V14h26v16" fill="#34493f"/><path d="M62 34l-23 14m79-14 23 14" stroke="#34493f" stroke-width="7"/>`}<path d="M70 79h11m18 0h11" stroke="#51453a" stroke-width="3"/><path d="M88 84l-3 10h8M81 102q9 5 19-1" stroke="#a57257" fill="none" stroke-width="2"/>${i%3===0?'<path d="M76 105q13 9 28 0l-7 33-13 8Z" fill="#3b493e"/>':i%3===1?'<path d="M74 102q6-6 13 0m6 0q9-6 14 0" stroke="#4b493e" stroke-width="3" fill="none"/>':''}${warrior?'<path d="M34 135l21-21 18 26m74-5-21-21-18 26" fill="#a8b0a0" stroke="#d5c6a0" stroke-width="2"/>':'<path d="M117 127l18-15 8 45-16 6Z" fill="#b9bb85" stroke="#7b8a62"/>'}<path d="M20 159h140" stroke="#c7c5a3"/></svg>`}
function heroesView(){let content='';if(state.heroTab===0){let list=heroes.filter((h,i)=>(state.heroFilter==='全部'||(state.heroFilter==='已定居'?i===0:state.heroFilter==='已发现'?i>0&&i<6:i>=6))&&h.name.includes(state.query));content=`<div class="tabs">${['全部','已定居','已发现','未寻得'].map(n=>`<button data-filter="${n}" class="${state.heroFilter===n?'active':''}">${n}</button>`).join('')}<input class="search" aria-label="搜索名将" placeholder="寻一位故人…" value="${esc(state.query)}" id="hero-search"></div><div class="hero-grid">${list.map(h=>{let i=heroes.indexOf(h);return `<button class="hero-card ${i>5?'locked':''}" data-hero="${i}"><div class="hero-art">${portrait(h,i)}</div><div class="hero-info"><h3>${h.name}</h3><p>${esc(h.suggested_use)}</p><span class="pill">${i===0?'已定居 · 官署':i<6?'已发现 · 可查看线索':'未寻得 · 成长中相见'}</span></div></button>`}).join('')}</div>`}else{const items=state.heroTab===1?['亮银枪','龙胆枪','青龙偃月刀','丈八蛇矛','青釭剑','七星宝刀']:['黄骠马','赤兔','的卢','绝影','开城木印'];content=`<div class="collection-grid">${items.map((n,i)=>`<article class="card"><div class="artifact">${state.heroTab===1?'<svg width="150" height="110" viewBox="0 0 150 110"><path d="M25 90L113 17" stroke="#8b7653" stroke-width="7"/><path d="M95 32l29-23-7 30-14 5Z" fill="#9daea0" stroke="#62766a" stroke-width="2"/></svg>':n==='开城木印'?'印':'♞'}</div><h3>${n}</h3><p class="short">${n==='开城木印'?'陈列于官署 · 首日的纪念':'尚未拥有 · 每件都是唯一实体'}</p><button data-artifact="${n}">查看藏品</button></article>`).join('')}</div><p class="muted">藏品形象为类别占位示意；不是最终独立兵器与坐骑美术。</p>`}return `<div class="tabs">${['名将 · 30','兵器 · 6','坐骑与纪念'].map((n,i)=>`<button data-herotab="${i}" class="${state.heroTab===i?'active':''}">${n}</button>`).join('')}</div><div class="banner">当前心愿：<strong>${state.wish||'尚未选择'}</strong>　·　最多 1 个主动心愿，3 个关注。无需 29 条招募通知。<br><span class="muted">名将四维取自 v0.7.2 配置；发现状态为演示，头像为程序绘制的风格占位。</span></div>${content}${review('宝鉴是否更像“等待故人到来”，而不是每日需要清红点的收集界面？')}`}
function army(){return `<div class="banner">设计目标 · 当前原生版本尚未完成军团与出征。本页只演示流程与状态区分。</div><div class="layout">${map({focus:'1210 120 650 790',line:'南门军营 · 准备中'})}<div class="stack">${card('军团规模',`<div class="army-number">18 <small>/ ${state.army}</small></div><p class="muted">实际现役 / 已授权上限</p>${row('正在训练','6 人')}${row('尚未招募',state.army-24+' 人')}<div class="tabs">${[30,60,90].map(n=>`<button data-army="${n}" class="${state.army===n?'active':''}">${n} 人</button>`).join('')}</div><p class="muted">切换只预览授权，不会凭空生成士兵。</p>`)}${card('护送商队 · 尚待准备',row('军粮','120 / 510')+progress(24)+row('国库','1,280 / 400 铜')+row('器材','8 / 4')+'<button class="wide" disabled>军粮与兵员未齐，暂不可出发</button><p class="muted">30 人护送样例：60 储备 + 30 × 15 = 510 军粮，预计 12 小时。</p>')}</div></div>${review('准备过程是否有期待感？战斗不抢走经营的重心，也不自动消耗民食。')}`}
function region(){const cities=['平川','石邑','河津'];return `<div class="banner">设计目标 · 通用跨城运输、新城建设与调任尚未完整交付。本幕没有真实交易或迁居。</div><div class="layout"><div class="region-map"><svg viewBox="0 0 1000 650" aria-label="三城区域路线图"><rect width="1000" height="650" fill="#e0e5cd"/><path d="M680-40Q450 80 580 230T700 430T650 700" fill="none" stroke="#9cbcae" stroke-width="64"/><path d="M0 570Q300 380 510 520T1100 420" stroke="#cad6b4" stroke-width="100" fill="none"/>${[50,140,250,740,830,900].map((x,i)=>`<path d="M${x} ${180+i%2*20}l60-105 75 105Z" fill="#b9c5a3"/><path d="M${x+30} ${180+i%2*20}l60-80 75 80Z" fill="#cad3b7"/>`).join('')}<path d="M260 420L470 200L780 430Z" fill="none" stroke="#a79364" stroke-width="3" stroke-dasharray="9 8"/><text x="310" y="300" fill="#6d7962" font-size="18">20 分钟</text><text x="650" y="300" fill="#6d7962" font-size="18">35 分钟</text><text x="470" y="460" fill="#6d7962" font-size="18">15 分钟</text>${[[260,420],[470,200],[780,430]].map(([x,y],i)=>`<g class="region-node" data-region="${i}" tabindex="0" role="button" aria-label="${cities[i]}"><circle cx="${x}" cy="${y}" r="61" fill="${state.region===i?'#f8f1d7':'#d3dabd'}" stroke="#a4b18f"/><path d="M${x-28} ${y-10}h56v34h-56Z" fill="#d6c7a0"/><path d="M${x-39} ${y-10}l15-22h48l15 22Z" fill="#5e7966"/><text x="${x}" y="${y+87}" text-anchor="middle" font-size="25" fill="#334d3d">${cities[i]}</text><text x="${x}" y="${y+111}" text-anchor="middle" font-size="13" fill="#76836b">${['已有城镇','石材产地 · 待勘察','河港商路 · 待勘察'][i]}</text></g>`).join('')}</svg></div><div class="stack">${card(cities[state.region],`<p class="short">${['你的第一座城。区域只有一个国库，物资仍分地点保管。','山地石材据点。先勘察，再把真实材料送到工地。','沿河的贸易节点。迁居需要床位、供给与旅途时间。'][state.region]}</p><div class="timeline">${['勘察地点','运输建材','建设基础设施','住民迁入','官员交接'].map((s,i)=>`<div><strong>${i+1} · ${s}</strong><p>${i===4?'原地交接 120 秒 → 旅行 → 到任交接 120 秒':'没有瞬间复制出的建筑、物资或人物。'}</p></div>`).join('')}</div><button class="wide" data-action="survey">查看勘察提案</button>`)}</div></div>${review('三城是否足够产生拓展欲望？先把旅行和运输表现清楚，再扩张地图规模。')}`}
function memories(){return `<div class="banner">成长册样例 · 同一机位，左右拖动比较。这里的“第 30 日”是美术设计快照，不代表已验证的成长速度。</div><div class="compare"><div class="after">${map({overlay:false})}</div><div class="before">${map({young:true,overlay:false})}</div><div class="compare-line"></div></div><div class="row"><span>开城第一日</span><span class="pill">同一视角 · 拖动下方滑块</span><span>第 30 日 · 目标印象</span></div><input type="range" id="compare-range" aria-label="前后对比位置" min="0" max="100" value="50"><div class="flow">${['第一锅饭的香气','官署修好了','第一位故人入城','夜里有了更多灯'].map((s,i)=>card(s,`<p>成长节点示例 · ${i+1}</p><button data-memory="${s}">钉入成长册</button>`)).join('')}</div><p class="muted">规则：自动保留 60 条，最多置顶 20 条；不要求手动领取成长奖励。</p>${review('这种前后对比能否让你觉得“之前的等待有意义”？哪些瞬间值得自动留下？')}`}
function desktop(){return `<div class="desktop"><div class="desktop-menu">●　访达　　文件　编辑　显示 <span style="float:right">星期一　14:36</span></div><div class="desktop-icons"><div><b>▣</b>工作资料</div><div><b>▤</b>随手记</div></div>${map({overlay:false})}<div class="desktop-dock">▣ ◉ ▤ ◇ ▧</div></div><div class="flow">${card('看看我的城','<p>默认不常驻大面板，需要时才进入交互视图。</p><button data-action="peek">展开轻量提示</button>')}${card('静一点也很好','<p>暂停只控制原型动效，不代表暂停实际经济。</p><button data-action="quiet">切换动效</button>')}${card('渲染不改变规则','<p>48 / 96 / 160 绘制档位只影响表现。</p><button data-action="render">查看表现设置</button>')}${card('工作不被打断','<p>不主动抢焦点，不靠限时损失吸引注意。</p><span class="pill">桌面合成示意</span>')}</div>${review('桌面占用面积是否过大？这张是合成示意，真正的透明窗、鼠标穿透、多屏需要原生实现验收。')}`}
const renders={opening,day,logistics,husbandry,night,construction,direction,heroes:heroesView,army,region,memories,desktop};
function render(){const s=scenes.find(s=>s[0]===state.scene)||scenes[0];$('#nav').innerHTML=scenes.map((n,i)=>`<a href="#${n[0]}" class="${n[0]===state.scene?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${n[1]}</a>`).join('');$('#chapter').textContent=s[2];$('#title').textContent=s[1];$('#subtitle').textContent=s[3];$('#content').innerHTML=renders[state.scene]();$('#content').className='reveal'}
function worker(){modal('陈伯 · 挑夫',`<span class="pill">居民 R-008 · 日班</span>${row('当前职责','必要物流')}${row('正在做','携粮前往共用厨房')}${row('携货','食粮 4 份')}${row('下一节点','厨房入口 → 卸货')}${row('步行速度','肩挑 32 地图单位 / 秒')}${row('劳动效率','100% · 演示快照')}<p class="muted">来源：田边批次 GRAIN-DEMO-004。卸货完成前，目的地库存不可消费。路线动画是示意，不是实时模拟。</p>`)}
document.addEventListener('click',e=>{const t=e.target.closest('[data-opening],[data-meal],[data-pig],[data-build],[data-policy],[data-herotab],[data-filter],[data-hero],[data-army],[data-region],[data-action],[data-building],[data-worker],[data-artifact],[data-memory]');if(!t)return;let d=t.dataset;for(const [key,prop] of [['opening','opening'],['meal','meal'],['pig','pig'],['build','build'],['policy','policy'],['herotab','heroTab'],['army','army'],['region','region']])if(d[key]!==undefined){state[prop]=Number(d[key]);render();return}if(d.filter){state.heroFilter=d.filter;render();return}if(d.hero!==undefined){let i=+d.hero,h=heroes[i];modal(h.name,`<div class="hero-art">${portrait(h,i)}</div>${row('推荐职责',esc(h.suggested_use))}${Object.entries(h.attributes).map(([k,v])=>row(({administration:'政治',strategy:'智力',valor:'武力',command:'统率'})[k],v)).join('')}<p class="short">${i===0?'开局已定居，由荀彧在官署主持民生。':'招募模板：'+esc(h.recruitment_profile)+'。线索、等待、供给与床位满足后才可定居。'}</p>${i>0?`<button class="primary wide" data-wish="${esc(h.name)}">设为唯一心愿（演示）</button>`:''}`);return}if(d.building!==undefined){let b=buildings[+d.building];modal(b[1],`<span class="pill">平川 · 固定地块 ${d.building}</span><p>点击建筑时展开轻量详情，不让整张地图变成管理表格。</p><div class="flow" style="grid-template-columns:1fr 1fr">${['生产','发运','到货','实际消纳'].map(n=>card(n,'<p>查看对应批次记录</p>')).join('')}</div><p class="muted">本原型未接入实际库存；数字和状态需由游戏引擎提供。</p>`);return}if(d.worker!==undefined){worker();return}if(d.artifact){modal(d.artifact,'<p>唯一藏品：所有者、保管位置、来源和获得时间都应明确。</p><div class="divider"></div><p>当前为外观与信息结构预览，尚未生成真实藏品。</p>');return}if(d.memory){t.textContent='已置顶（演示）';t.disabled=true;toast('已在本页演示置顶；刷新后不保存');return}switch(d.action){case'worker':case'follow':worker();break;case'nextmeal':state.meal=(state.meal+1)%5;render();break;case'nextpig':state.pig=(state.pig+1)%6;render();break;case'pigpause':t.textContent=t.textContent.includes('暂停')?'恢复后续采购（演示）':'暂停后续采购（演示）';toast('只切换演示状态；已购动物仍应被照料');break;case'seal':modal('一枚开城木印','<div class="artifact">平 川<br>初 建</div><p>10 铜 · 木材 2 · 360 人工秒。制作完成后陈列在官署。</p><button class="primary wide" data-action="sealconfirm">授权制作（演示）</button>');break;case'sealconfirm':$('#dialog').close();toast('已演示授权；真实制作尚未执行');break;case'policy':toast('已预览「'+policies[state.policy][0]+'」；已有建筑不会被拆除');break;case'patrol':modal('夜巡 · 南门至北巷','<p>南门 → 东侧大道 → 北巷 → 官署 → 南门。</p><p>固定夜班，白天休息；巡逻不要求你在线围观。</p>');break;case'survey':modal('勘察提案','<p>先了解目的地的资源和交通，再决定是否投入建设。</p><p>本次只展示信息结构；不消耗铜钱、不发送任何命令。</p>');break;case'quiet':$('#motion').click();break;case'peek':modal('平川今日','<p>正在：挑夫把饭送往北巷。</p><p>接下来：百工坊等待下一批石材。</p><p>最近完成：第一枚开城木印。</p>');break;case'render':modal('表现设置','<p>目标绘制档位：48 / 96 / 160 人。</p><p>帧率：8 / 15 / 30 FPS。只影响绘制，不影响生产和运输。</p><p class="muted">HTML 原型只支持全局暂停动效；其余设置属于原生实现目标。</p>');break}});
document.addEventListener('click',e=>{let t=e.target.closest('[data-wish]');if(t){state.wish=t.dataset.wish;$('#dialog').close();render();toast('已将 '+state.wish+' 设为演示心愿')}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[role=button]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
document.addEventListener('input',e=>{if(e.target.id==='build-range'){state.build=+e.target.value;$('.layout .scene').outerHTML=map({build:true,focus:'930 40 930 820',line:'百工坊 · 施工 '+state.build+'%'});$('.army-number').innerHTML=state.build+'<small>%</small>'}if(e.target.id==='compare-range'){let v=e.target.value;$('.before').style.clipPath=`inset(0 ${100-v}% 0 0)`;$('.compare-line').style.left=v+'%'}if(e.target.id==='hero-search'){state.query=e.target.value;let pos=e.target.selectionStart;render();$('#hero-search').focus();$('#hero-search').setSelectionRange(pos,pos)}});
function route(){let id=location.hash.slice(1);state.scene=scenes.some(s=>s[0]===id)?id:'opening';render()}window.addEventListener('hashchange',route);
fetch('../../spec/heroes-v0.7.2.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(j=>{heroes=j.heroes;if(state.scene==='heroes')render()}).catch(()=>{toast('名将配置读取失败：请通过本地 HTTP 服务打开，而不是直接双击文件')});route();
